import {esc} from './core.js';import {companionAPI,isCompanion} from './companion-client.js';
export function createCompanionUI(ui){let health=null,error='';const {button,tag,showDialog}=ui;
 async function show(){health=null;error='';if(isCompanion())try{health=await companionAPI('readiness')}catch(e){error=e.message;}showDialog('Companion status',`<p class="help-copy">Native tools run on the assessment computer. The hosted app reviews portable evidence.</p><div class="row wrap spaced">${button('Setup / pair','scan-setup','primary')}${button('Refresh status','companion-status','small')}${button('Export diagnostics','companion-diagnostics','small','download',health?'':'disabled')}</div>${error?`<p class="notice spaced">${esc(error)}</p>`:''}${health?`<div class="stack spaced">${Object.entries(health.tools).map(([name,t])=>`<div class="baseline-row"><div class="row between"><strong>${esc(name)}</strong>${tag(t.available?'AVAILABLE':'UNAVAILABLE')}</div><p class="smalltext spaced">${esc(t.version||t.python||t.error||'No version available')}</p><p class="muted smalltext spaced">${esc(t.next)}</p></div>`).join('')}</div><h3 class="spaced">Retained acquisitions</h3><div class="table-wrap"><table><thead><tr><th>Tool</th><th>Retained</th><th>Active</th><th>Interrupted / failed</th></tr></thead><tbody>${Object.entries(health.jobs).map(([name,j])=>`<tr><td>${esc(name)}</td><td>${j.retained}</td><td>${j.active}</td><td>${j.interrupted} / ${j.failed}</td></tr>`).join('')}</tbody></table></div><p class="notice spaced">${esc(health.recovery)}</p>`:'<p class="notice spaced">Launch the portable companion and open its printed local URL. Pair once, then use this view to check every native tool.</p>'}<h3 class="spaced">Archive and start a new collection</h3><p class="help-copy spaced">Export the project and preserve completed jobs first. Stop the companion, then copy its evidence into a new verified archive:</p><pre class="scan-command">node companion/archive.mjs --data-dir SOURCE --output NEW_DIRECTORY</pre><p class="muted smalltext spaced">The command copies regular files, verifies hashes and keeps the source intact. Start the next collection using a different --data-dir. Diagnostics omit targets, paths, tokens and evidence content.</p>`);}
 return {async action(name){if(name==='companion-status'){await show();return true;}if(name==='companion-diagnostics'){const d=await companionAPI('diagnostics');ui.download('PROBE-diagnostics.json',JSON.stringify(d,null,2));return true;}return false;}};
}
